from solution import f
import math
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference(n):
    out = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            out.append(math.factorial(i))
        else:
            out.append(i * (i + 1) // 2)
    return out


def test_example_from_spec_f5():
    assert f(5) == [1, 2, 6, 24, 15]


def test_zero_returns_empty_list():
    assert f(0) == []


def test_one_returns_singleton():
    assert f(1) == [1]


def test_two_returns_first_two():
    assert f(2) == [1, 2]


def test_three_returns_first_three():
    assert f(3) == [1, 2, 6]


def test_four_returns_first_four():
    assert f(4) == [1, 2, 6, 24]


def test_length_equals_n():
    for n in [0, 1, 2, 3, 4, 5, 6, 10, 20]:
        assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=50))
def test_length_property(n):
    assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=30))
def test_equivalence_to_reference_model(n):
    assert f(n) == reference(n)


@given(st.integers(min_value=0, max_value=30))
def test_even_i_is_factorial(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 0:
            assert res[i - 1] == math.factorial(i)


@given(st.integers(min_value=0, max_value=30))
def test_odd_i_is_triangular_sum(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert res[i - 1] == i * (i + 1) // 2
            assert res[i - 1] == sum(range(1, i + 1))


@given(st.integers(min_value=0, max_value=30))
def test_all_elements_positive_ints(n):
    res = f(n)
    assert isinstance(res, list)
    for v in res:
        assert type(v) == int
        assert v >= 1


@given(st.integers(min_value=0, max_value=30))
def test_prefix_consistency(n):
    full = f(n)
    for k in range(n + 1):
        assert f(k) == full[:k]


@given(st.integers(min_value=1, max_value=30))
def test_last_element_definition(n):
    res = f(n)
    if n % 2 == 0:
        assert res[-1] == math.factorial(n)
    else:
        assert res[-1] == n * (n + 1) // 2


def test_returns_fresh_list_each_call():
    a = f(5)
    b = f(5)
    assert a == b
    assert a is not b
    a.append(999)
    assert f(5) == [1, 2, 6, 24, 15]
